(() => {
  'use strict';
  const app = window.pythonMbb;
  app.legacyExercises = {
    title: "99. Exercícios",
    objective: "Praticar Python com 170 exercícios progressivos, organizados em sete níveis.",
    html: "\n<div class=\"theory-page exercises-99\">\n\n<div class=\"theory-hero\">\n<h3>99 — Exercícios de Lógica com Python</h3>\n<p>Esta página reúne exercícios para praticar lógica de programação. Não é necessário fazer tudo de uma vez: comece pelo nível em que você está, use as dicas quando travar e avance aos poucos.</p>\n</div>\n<div class=\"intro-grid\">\n<div class=\"intro-box\"><strong>Como estudar</strong><br/>Leia o enunciado com calma, identifique entradas, processamento e saída antes de programar.</div>\n<div class=\"intro-box\"><strong>Dicas</strong><br/>Passe o mouse ou toque sobre o selo 💡 Dica para receber uma orientação rápida sem ver a resposta pronta.</div>\n<div class=\"intro-box\"><strong>Exemplos resolvidos</strong><br/>Cada nível técnico começa com um modelo completo para ajudar a entender a estrutura do bloco.</div>\n</div>\n<section class=\"exercise-level\"><h3>Fundamentos</h3><p>Objetivo: praticar entrada e saída de dados, variáveis, atribuição, operadores aritméticos, conversões e cálculos simples.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Variáveis, entrada, saída e cálculo</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma loja deseja calcular o valor total de uma compra. O programa deve ler o preço unitário de um produto, a quantidade comprada e exibir o total a pagar.</p></div>\n<h4>Programa em Python</h4>\n<pre>preco = float(input(\"Digite o preço do produto: \"))\nquantidade = int(input(\"Digite a quantidade comprada: \"))\n\ntotal = preco * quantidade\n\nprint(f\"Total da compra: R$ {total:.2f}\")</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos variáveis ao receber os dados da compra.</li><li>Usamos input() e conversões para ler preço e quantidade.</li><li>Calculamos o valor total multiplicando o preço pela quantidade.</li><li>Exibimos o resultado com print().</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 1 — Saudação ao Usuário</strong>\n<p>Crie um programa que leia o nome de uma pessoa e exiba uma mensagem de boas-vindas contendo o nome informado.</p>\n<span class=\"badge\" title=\"Você precisa de uma variável de texto (str) para guardar o nome.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 2 — Soma de Dois Valores</strong>\n<p>Desenvolva um programa que leia dois números inteiros, calcule a soma entre eles e mostre o resultado na tela.</p>\n<span class=\"badge\" title=\"Leia dois valores, some os dois e guarde o resultado em uma terceira variável.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 3 — Média de Três Notas</strong>\n<p>Uma escola precisa calcular a média de um aluno. Leia três notas, calcule a média aritmética e exiba o resultado final.</p>\n<span class=\"badge\" title=\"Some as três notas e divida o total por 3.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 4 — Dobro e Metade</strong>\n<p>Leia um número informado pelo usuário e mostre o dobro e a metade desse valor.</p>\n<span class=\"badge\" title=\"O dobro usa multiplicação. A metade usa divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 5 — Idade Futura</strong>\n<p>Leia a idade atual de uma pessoa e informe quantos anos ela terá daqui a 5 anos.</p>\n<span class=\"badge\" title=\"Some 5 ao valor digitado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 6 — Área de um Terreno</strong>\n<p>Um cliente deseja saber a área de um terreno retangular. Leia a largura e o comprimento do terreno e calcule a área total.</p>\n<span class=\"badge\" title=\"Área do retângulo = largura × comprimento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 7 — Área do Triângulo</strong>\n<p>Leia a base e a altura de um triângulo e calcule sua área.</p>\n<span class=\"badge\" title=\"Área do triângulo = base × altura ÷ 2.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 8 — Área do Círculo</strong>\n<p>Leia o raio de um círculo e calcule sua área.</p>\n<span class=\"badge\" title=\"Área do círculo = π × raio².\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 9 — Conversão de Temperatura</strong>\n<p>Leia uma temperatura em graus Celsius e converta para Fahrenheit.</p>\n<span class=\"badge\" title=\"Use a fórmula: Fahrenheit = Celsius × 1.8 + 32.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 10 — Reajuste Salarial</strong>\n<p>Uma empresa concedeu reajuste de 8% aos funcionários. Leia o salário atual e calcule o novo salário.</p>\n<span class=\"badge\" title=\"Calcule 8% do salário e some ao salário original.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 11 — Velocidade Média</strong>\n<p>Leia a distância percorrida por um veículo e o tempo gasto na viagem. Calcule e exiba a velocidade média.</p>\n<span class=\"badge\" title=\"Velocidade média = distância ÷ tempo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 12 — Total de Compra</strong>\n<p>Leia o nome de um produto, seu preço unitário e a quantidade comprada. Exiba o nome do produto e o valor total da compra.</p>\n<span class=\"badge\" title=\"Valor total = preço unitário × quantidade.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 13 — Conversão de Moeda</strong>\n<p>Leia um valor em reais e a cotação atual do dólar. Calcule quantos dólares podem ser comprados.</p>\n<span class=\"badge\" title=\"Divida o valor em reais pela cotação do dólar.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 14 — Média Bimestral</strong>\n<p>Um professor precisa calcular a média final de um aluno. Leia quatro notas bimestrais e exiba a média aritmética.</p>\n<span class=\"badge\" title=\"Some as quatro notas e divida por 4.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 15 — Dias em Horas</strong>\n<p>Leia uma quantidade de dias e converta esse valor para horas.</p>\n<span class=\"badge\" title=\"Cada dia possui 24 horas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 16 — Horas em Minutos</strong>\n<p>Leia uma quantidade de horas e converta para minutos.</p>\n<span class=\"badge\" title=\"Cada hora possui 60 minutos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 17 — Minutos em Segundos</strong>\n<p>Leia uma quantidade de minutos e converta para segundos.</p>\n<span class=\"badge\" title=\"Cada minuto possui 60 segundos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 18 — Antecessor e Sucessor</strong>\n<p>Leia um número inteiro e mostre seu antecessor e seu sucessor.</p>\n<span class=\"badge\" title=\"O antecessor é o número menos 1. O sucessor é o número mais 1.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 19 — Divisão de Conta</strong>\n<p>Três amigos foram a uma lanchonete e decidiram dividir a conta igualmente. Leia o valor total da conta e mostre quanto cada um deverá pagar.</p>\n<span class=\"badge\" title=\"Divida o valor total por 3.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 20 — Caixas e Garrafas</strong>\n<p>Uma distribuidora armazena refrigerantes em caixas com 12 garrafas. Leia a quantidade total de garrafas e informe:</p>\n<ul><li>Quantas caixas completas podem ser montadas.</li><li>Quantas garrafas sobram sem completar uma caixa.</li></ul>\n<span class=\"badge\" title=\"Utilize divisão inteira e resto da divisão.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Decisão</h3><p>Objetivo: praticar decisões simples, compostas, encadeadas e operadores booleanos.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Decisão com if e else</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja verificar se um aluno foi aprovado. O programa deve ler a nota final e mostrar se o aluno foi aprovado ou reprovado.</p></div>\n<h4>Programa em Python</h4>\n<pre>nota = float(input(\"Digite a nota final: \"))\n\nif nota &gt;= 6:\n    print(\"Aprovado\")\nelse:\n    print(\"Reprovado\")</pre>\n<h4>Explicação</h4>\n<ol><li>Associamos o nome nota ao valor digitado.</li><li>Lemos a nota digitada.</li><li>Usamos if/else para separar os dois caminhos possíveis.</li><li>Se a nota for maior ou igual a 6, mostramos aprovado. Caso contrário, mostramos reprovado.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 21 — Aprovado ou Reprovado</strong>\n<p>Uma escola deseja automatizar a análise das notas dos alunos. Desenvolva um programa que leia a nota final de um estudante. Caso a nota seja maior ou igual a 6, exiba \"Aprovado\". Caso contrário, exiba \"Reprovado\".</p>\n<span class=\"badge\" title=\"Existem apenas duas possibilidades de resultado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 22 — Número Positivo ou Negativo</strong>\n<p>Leia um número informado pelo usuário e determine se ele é positivo, negativo ou igual a zero.</p>\n<span class=\"badge\" title=\"Observe que existem três possíveis classificações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 23 — Par ou Ímpar</strong>\n<p>Desenvolva um programa que leia um número inteiro e informe se ele é par ou ímpar.</p>\n<span class=\"badge\" title=\"Utilize o operador de resto da divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 24 — Maioridade</strong>\n<p>Leia a idade de uma pessoa e informe se ela já atingiu a maioridade legal.</p>\n<span class=\"badge\" title=\"Compare a idade informada com 18 anos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 25 — Comparação entre Dois Valores</strong>\n<p>Leia dois números inteiros e informe qual deles possui o maior valor. Caso sejam iguais, informe essa situação ao usuário.</p>\n<span class=\"badge\" title=\"Nem sempre um valor será maior que o outro.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 26 — Validação de Nota</strong>\n<p>Leia a nota de um aluno. Caso a nota esteja fora do intervalo de 0 a 10, exiba a mensagem \"Nota inválida\". Caso contrário, exiba a nota informada.</p>\n<span class=\"badge\" title=\"Primeiro valide os dados recebidos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 27 — Classificação de Desempenho</strong>\n<p>Leia a nota final de um estudante e classifique: aprovado se for igual ou superior a 7; recuperação se estiver entre 5 e 6,9; reprovado se for inferior a 5.</p>\n<span class=\"badge\" title=\"Existem três faixas diferentes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 28 — Faixa Etária</strong>\n<p>Leia a idade de uma pessoa e classifique como criança, adolescente, adulto ou idoso, usando faixas de idade coerentes para cada categoria.</p>\n<span class=\"badge\" title=\"Será necessário trabalhar com intervalos.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 29 — Saudação por Horário</strong>\n<p>Leia uma hora inteira entre 0 e 23. Exiba bom dia, boa tarde ou boa noite de acordo com o horário. Caso o valor esteja fora do intervalo, informe que a hora é inválida.</p>\n<span class=\"badge\" title=\"Primeiro verifique se a hora é válida.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 30 — Sistema de Login</strong>\n<p>Desenvolva um programa que leia um nome de usuário e uma senha. Considere usuário correto admin e senha correta 1234. Informe se o acesso foi autorizado ou negado.</p>\n<span class=\"badge\" title=\"As duas condições precisam ser verdadeiras.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 31 — Código de Região</strong>\n<p>Uma empresa utiliza códigos para regiões: 1 Norte, 2 Sul, 3 Leste e 4 Oeste. Leia um código e informe a região correspondente. Caso o código não exista, informe \"Região não cadastrada\".</p>\n<span class=\"badge\" title=\"Compare o valor digitado com várias opções.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 32 — Controle de Velocidade</strong>\n<p>Leia a velocidade registrada por um veículo. Classifique como dentro do limite até 80 km/h, infração leve de 81 a 100 km/h e infração grave acima de 100 km/h.</p>\n<span class=\"badge\" title=\"Analise intervalos de valores.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 33 — Intervalo Numérico</strong>\n<p>Leia um número inteiro e informe se ele pertence ao intervalo entre 10 e 20, inclusive.</p>\n<span class=\"badge\" title=\"Será necessário utilizar duas comparações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 34 — Múltiplo de 3 e de 5</strong>\n<p>Leia um número inteiro e informe se ele é múltiplo de 3 e de 5 ao mesmo tempo.</p>\n<span class=\"badge\" title=\"Duas condições precisam ser satisfeitas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 35 — Verificação de Triângulo</strong>\n<p>Leia três valores que representam lados de um possível triângulo. Informe se esses valores podem formar um triângulo.</p>\n<span class=\"badge\" title=\"Nem toda combinação de três lados forma um triângulo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 36 — Classificação de Triângulo</strong>\n<p>Após verificar que três lados formam um triângulo, classifique-o em equilátero, isósceles ou escaleno.</p>\n<span class=\"badge\" title=\"Observe quais lados possuem medidas iguais.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 37 — Empréstimo Bancário</strong>\n<p>Um banco analisa pedidos de crédito. Leia o salário do cliente e o valor solicitado. O empréstimo será aprovado apenas se o valor solicitado não ultrapassar quatro vezes o salário informado.</p>\n<span class=\"badge\" title=\"Compare o valor solicitado com um limite calculado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 38 — Reajuste Salarial por Faixa</strong>\n<p>Uma empresa definiu reajustes por faixa: até R$ 2.000 aumento de 12%; de R$ 2.000,01 até R$ 4.000 aumento de 8%; acima de R$ 4.000 aumento de 5%. Leia o salário atual e exiba o novo salário.</p>\n<span class=\"badge\" title=\"Cada faixa possui uma regra diferente.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 39 — Cálculo de IMC</strong>\n<p>Leia peso e altura de uma pessoa. Calcule o IMC e classifique como abaixo do peso, peso normal, sobrepeso ou obesidade.</p>\n<span class=\"badge\" title=\"Primeiro faça o cálculo. Depois classifique.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 40 — Ordenação de Três Valores</strong>\n<p>Leia três números inteiros e exiba os valores em ordem crescente.</p>\n<span class=\"badge\" title=\"Pense em como descobrir qual é o menor, o intermediário e o maior valor.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Repetição</h3><p>Objetivo: praticar contadores, acumuladores, médias, estatísticas e problemas com repetição.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Repetição com for</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja exibir os números de chamada dos alunos de uma turma. Desenvolva um programa que mostre os números de 1 até 10 na tela.</p></div>\n<h4>Programa em Python</h4>\n<pre>for contador in range(1, 11):\n    print(contador)</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos uma variável contador.</li><li>O laço começa em 1 e termina em 10.</li><li>A cada repetição, o valor do contador é exibido.</li><li>Quando o contador passa do limite, a repetição termina.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 41 — Contagem Crescente</strong>\n<p>Desenvolva um programa que exiba na tela todos os números inteiros de 1 até 20.</p>\n<span class=\"badge\" title=\"Você não precisa criar vinte comandos de escrita.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 42 — Contagem Regressiva</strong>\n<p>Crie um programa que exiba os números de 20 até 1 em ordem decrescente.</p>\n<span class=\"badge\" title=\"O contador deverá diminuir a cada repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 43 — Números Pares</strong>\n<p>Desenvolva um programa que exiba todos os números pares entre 2 e 50.</p>\n<span class=\"badge\" title=\"Existe mais de uma forma de resolver esse problema.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 44 — Números Ímpares</strong>\n<p>Exiba todos os números ímpares entre 1 e 49.</p>\n<span class=\"badge\" title=\"Observe o padrão de crescimento da sequência.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 45 — Contando de Cinco em Cinco</strong>\n<p>Mostre na tela os números de 0 até 100, avançando de cinco em cinco.</p>\n<span class=\"badge\" title=\"Nem todo laço precisa incrementar de um em um.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 46 — Contagem Regressiva de Lançamento</strong>\n<p>Desenvolva um programa que exiba uma contagem de 10 até 1 e, ao final, mostre a mensagem \"Lançamento!\".</p>\n<span class=\"badge\" title=\"Primeiro faça a contagem. Depois exiba a mensagem final.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 47 — Soma de 1 até 100</strong>\n<p>Calcule a soma de todos os números inteiros entre 1 e 100 e exiba o resultado final.</p>\n<span class=\"badge\" title=\"Você precisará de uma variável acumuladora.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 48 — Soma dos Números Pares</strong>\n<p>Calcule a soma de todos os números pares entre 2 e 100.</p>\n<span class=\"badge\" title=\"Nem todos os números devem participar da soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 49 — Tabuada</strong>\n<p>Leia um número inteiro informado pelo usuário e exiba sua tabuada de multiplicação de 1 até 10.</p>\n<span class=\"badge\" title=\"O valor digitado será multiplicado várias vezes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 50 — Dez Números e uma Soma</strong>\n<p>Solicite ao usuário dez números inteiros. Ao final, exiba a soma de todos os valores digitados.</p>\n<span class=\"badge\" title=\"A cada leitura, atualize o total acumulado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 51 — Média de uma Turma</strong>\n<p>Um professor deseja calcular a média de uma turma. Desenvolva um programa que leia as notas de 10 alunos e, ao final, exiba a média da turma.</p>\n<span class=\"badge\" title=\"Você precisará acumular todas as notas antes de calcular a média.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 52 — Contando Valores Positivos</strong>\n<p>Solicite ao usuário 15 números inteiros. Ao final, informe quantos deles são positivos.</p>\n<span class=\"badge\" title=\"Crie um contador que aumente apenas quando a condição for verdadeira.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 53 — Contando Valores Negativos</strong>\n<p>Leia 15 números inteiros e informe quantos valores negativos foram digitados.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 54 — Quantidade de Números Pares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são pares.</p>\n<span class=\"badge\" title=\"Utilize o operador de resto da divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 55 — Quantidade de Números Ímpares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são ímpares.</p>\n<span class=\"badge\" title=\"Nem todos os números digitados devem ser contabilizados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 56 — Maior Valor Informado</strong>\n<p>Solicite ao usuário 10 números inteiros. Ao final, exiba qual foi o maior valor digitado.</p>\n<span class=\"badge\" title=\"Você precisará guardar temporariamente o maior valor encontrado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 57 — Menor Valor Informado</strong>\n<p>Leia 10 números inteiros e informe qual foi o menor valor digitado.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 58 — Maior e Menor Valor</strong>\n<p>Leia 15 números inteiros e exiba, ao final, o maior e o menor valor encontrados.</p>\n<span class=\"badge\" title=\"Você precisará acompanhar duas informações durante o processamento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 59 — Média de Alturas</strong>\n<p>Uma academia deseja calcular a altura média de seus alunos. Leia a altura de 20 pessoas e exiba a média ao final.</p>\n<span class=\"badge\" title=\"Some todas as alturas antes de dividir.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 60 — Média de Idades</strong>\n<p>Leia a idade de 25 pessoas e calcule a média de idade do grupo.</p>\n<span class=\"badge\" title=\"O raciocínio é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 61 — Aprovados na Turma</strong>\n<p>Leia as notas de 20 alunos. Considere aprovado quem obtiver nota maior ou igual a 6. Ao final, informe quantos alunos foram aprovados.</p>\n<span class=\"badge\" title=\"Misture repetição com decisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 62 — Reprovados na Turma</strong>\n<p>Leia as notas de 20 alunos e informe quantos ficaram reprovados.</p>\n<span class=\"badge\" title=\"Você pode reutilizar a lógica do exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 63 — Pesquisa de Idades</strong>\n<p>Uma empresa realizou uma pesquisa com 30 pessoas. Leia as idades e informe a maior idade, a menor idade e a média das idades.</p>\n<span class=\"badge\" title=\"Será necessário combinar acumuladores e comparações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 64 — Pesquisa de Alturas</strong>\n<p>Leia a altura de 20 pessoas e informe a maior altura, a menor altura e a altura média.</p>\n<span class=\"badge\" title=\"Guarde os extremos encontrados durante a leitura.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 65 — Soma dos Múltiplos de 3</strong>\n<p>Calcule a soma de todos os múltiplos de 3 existentes entre 1 e 100.</p>\n<span class=\"badge\" title=\"Nem todos os números participam da soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 66 — Soma dos Múltiplos de 5</strong>\n<p>Calcule a soma de todos os múltiplos de 5 existentes entre 1 e 100.</p>\n<span class=\"badge\" title=\"Primeiro identifique quais valores atendem à condição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 67 — Quantos Estão no Intervalo</strong>\n<p>Leia 20 números inteiros e informe quantos deles estão entre 10 e 50, inclusive.</p>\n<span class=\"badge\" title=\"Será necessário usar uma condição dentro do laço.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 68 — Tabuadas de 1 a 10</strong>\n<p>Exiba as tabuadas completas dos números de 1 até 10.</p>\n<span class=\"badge\" title=\"Pense em uma repetição dentro de outra repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 69 — Fatorial</strong>\n<p>Leia um número inteiro positivo e calcule seu fatorial.</p>\n<span class=\"badge\" title=\"Você precisará multiplicar vários valores sucessivamente.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 70 — Número Primo</strong>\n<p>Leia um número inteiro positivo e informe se ele é primo.</p>\n<span class=\"badge\" title=\"Verifique quantos divisores o número possui.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 71 — Divisores de um Número</strong>\n<p>Desenvolva um programa que leia um número inteiro positivo e exiba todos os seus divisores.</p>\n<span class=\"badge\" title=\"Verifique quais números dividem o valor informado sem deixar resto.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 72 — Soma dos Divisores</strong>\n<p>Leia um número inteiro positivo e calcule a soma de todos os seus divisores.</p>\n<span class=\"badge\" title=\"Primeiro descubra os divisores. Depois some os valores encontrados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 73 — Sequência de Fibonacci</strong>\n<p>Exiba os 15 primeiros números da sequência de Fibonacci, começando em 0 e 1.</p>\n<span class=\"badge\" title=\"Cada novo termo é obtido pela soma dos dois anteriores.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 74 — Pesquisa de Satisfação</strong>\n<p>Uma empresa realizou uma pesquisa com 20 clientes. Cada cliente deve informar uma nota de 1 a 5. Ao final, exiba a média, a maior nota e a menor nota.</p>\n<span class=\"badge\" title=\"Você precisará acumular valores e comparar resultados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 75 — Pesquisa Eleitoral Simplificada</strong>\n<p>Durante uma pesquisa, 30 pessoas devem escolher entre três candidatos. Ao final, informe quantos votos cada candidato recebeu.</p>\n<span class=\"badge\" title=\"Crie um contador para cada opção.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 76 — Controle de Vendas</strong>\n<p>Uma loja deseja registrar o valor de 15 vendas realizadas durante o dia. Ao final, exiba o valor total vendido, a média das vendas e a maior venda realizada.</p>\n<span class=\"badge\" title=\"Nem todas as informações são calculadas da mesma forma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 77 — Estatística da Turma</strong>\n<p>Leia as notas de 25 alunos. Ao final, informe a média da turma, a quantidade de aprovados e a quantidade de reprovados.</p>\n<span class=\"badge\" title=\"Misture repetição, acumuladores e decisões.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 78 — Contagem de Faixas Etárias</strong>\n<p>Leia a idade de 20 pessoas. Ao final, informe quantas pertencem aos grupos criança, adolescente, adulto e idoso.</p>\n<span class=\"badge\" title=\"Cada faixa precisa de seu próprio contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 79 — Maior Sequência</strong>\n<p>Leia 15 números inteiros e determine qual foi o maior valor informado. Além disso, informe em qual posição ele foi digitado.</p>\n<span class=\"badge\" title=\"Você precisará acompanhar o valor e sua posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 80 — Controle de Estoque</strong>\n<p>Uma loja possui 10 produtos cadastrados. Para cada produto, informe a quantidade atual em estoque. Ao final, exiba o total de itens, o maior estoque e o menor estoque.</p>\n<span class=\"badge\" title=\"Guarde os extremos encontrados durante a leitura.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 81 — Média até Valor de Parada</strong>\n<p>Leia vários números até que seja digitado o valor 0. Ao final, exiba a média dos números digitados.</p>\n<span class=\"badge\" title=\"O valor que encerra a leitura não participa do cálculo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 82 — Soma até Valor de Parada</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, exiba a soma de todos os valores informados.</p>\n<span class=\"badge\" title=\"Esse exercício é semelhante ao anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 83 — Quantidade de Entradas</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, informe quantos números foram digitados.</p>\n<span class=\"badge\" title=\"Use um contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 84 — Maior Valor até Encerramento</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, informe qual foi o maior número digitado.</p>\n<span class=\"badge\" title=\"O valor de encerramento não deve ser considerado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 85 — Menor Valor até Encerramento</strong>\n<p>Leia números inteiros até que o usuário digite 0. Ao final, informe qual foi o menor número digitado.</p>\n<span class=\"badge\" title=\"Pense em como inicializar a variável que armazenará o menor valor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 86 — Soma dos Pares Informados</strong>\n<p>Leia 20 números inteiros e calcule a soma apenas dos números pares.</p>\n<span class=\"badge\" title=\"Nem todos os valores participam da soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 87 — Soma dos Ímpares Informados</strong>\n<p>Leia 20 números inteiros e calcule a soma apenas dos números ímpares.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 88 — Média dos Valores Positivos</strong>\n<p>Leia 20 números inteiros e calcule a média apenas dos valores positivos.</p>\n<span class=\"badge\" title=\"Você precisará controlar quantidade e soma.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 89 — Classificação de Temperaturas</strong>\n<p>Leia a temperatura registrada durante 30 dias. Ao final, informe maior temperatura, menor temperatura e temperatura média.</p>\n<span class=\"badge\" title=\"O raciocínio é semelhante ao das pesquisas anteriores.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 90 — Simulação de Caixa</strong>\n<p>Um caixa registrou 20 compras durante o dia. Leia o valor de cada compra e informe o faturamento total, a média das compras e a maior compra realizada.</p>\n<span class=\"badge\" title=\"Este exercício reúne vários conceitos já praticados neste nível.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Listas (listas)</h3><p>Objetivo: armazenar vários valores em uma única estrutura e percorrer suas posições.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Lista (lista) de notas</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja armazenar as notas de 5 alunos para exibi-las depois. Desenvolva um programa que leia as cinco notas, armazene-as em uma lista e mostre todas as notas digitadas.</p></div>\n<h4>Programa em Python</h4>\n<pre>notas = []\n\nfor i in range(5):\n    nota = float(input(f\"Digite a {i + 1}ª nota: \"))\n    notas.append(nota)\n\nprint(\"Notas cadastradas:\")\nfor nota in notas:\n    print(nota)</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos uma lista vazia e acrescentamos cinco notas.</li><li>O primeiro laço lê e guarda cada nota.</li><li>Cada nota ocupa uma posição diferente da lista.</li><li>O segundo laço percorre a lista para exibir os valores armazenados.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 91 — Cadastro de Valores</strong>\n<p>Desenvolva um programa que leia 10 números inteiros e os armazene em uma lista. Após a leitura, exiba todos os valores na mesma ordem em que foram digitados.</p>\n<span class=\"badge\" title=\"Primeiro armazene. Depois percorra a lista.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 92 — Ordem Inversa</strong>\n<p>Leia 10 números inteiros e armazene-os em uma lista. Ao final, exiba os valores na ordem inversa da digitação.</p>\n<span class=\"badge\" title=\"Percorra a lista do fim para o início.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 93 — Maior Elemento</strong>\n<p>Leia 15 números inteiros e armazene-os em uma lista. Ao final, informe qual é o maior valor armazenado.</p>\n<span class=\"badge\" title=\"Compare cada elemento com o maior encontrado até o momento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 94 — Menor Elemento</strong>\n<p>Leia 15 números inteiros e informe qual é o menor valor armazenado na lista.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 95 — Média dos Elementos</strong>\n<p>Leia 20 números reais e armazene-os em uma lista. Calcule e exiba a média dos valores armazenados.</p>\n<span class=\"badge\" title=\"Some todos os elementos antes de calcular a média.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 96 — Quantidade de Pares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são pares.</p>\n<span class=\"badge\" title=\"Percorra a lista verificando cada elemento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 97 — Quantidade de Ímpares</strong>\n<p>Leia 20 números inteiros e informe quantos deles são ímpares.</p>\n<span class=\"badge\" title=\"A solução é muito parecida com a do exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 98 — Procurando um Valor</strong>\n<p>Leia 10 números inteiros e armazene-os em uma lista. Em seguida, solicite um número ao usuário e informe se ele está presente na lista.</p>\n<span class=\"badge\" title=\"Será necessário percorrer todas as posições.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 99 — Localizando a Posição</strong>\n<p>Leia 10 números inteiros. Depois, solicite um valor para pesquisa. Caso ele exista na lista, informe em qual posição foi encontrado.</p>\n<span class=\"badge\" title=\"Guarde também o índice da posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 100 — Soma dos Elementos</strong>\n<p>Leia 15 números inteiros e calcule a soma de todos os valores armazenados na lista.</p>\n<span class=\"badge\" title=\"Use uma variável acumuladora.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 101 — Substituindo Negativos</strong>\n<p>Leia 15 números inteiros. Sempre que um valor negativo for encontrado, substitua-o por zero. Ao final, exiba a lista atualizada.</p>\n<span class=\"badge\" title=\"Você pode alterar o própria lista.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 102 — Contando Ocorrências</strong>\n<p>Leia 20 números inteiros. Em seguida, solicite um valor para pesquisa e informe quantas vezes ele aparece na lista.</p>\n<span class=\"badge\" title=\"Cada ocorrência encontrada aumenta um contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 103 — Lista (lista) Copiado</strong>\n<p>Leia 10 números inteiros em uma lista A. Copie todos os valores para uma lista B e exiba as duas listas.</p>\n<span class=\"badge\" title=\"Percorra ambos utilizando o mesmo índice.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 104 — Comparação de Lista (lista)es</strong>\n<p>Leia duas listas com 10 números inteiros cada. Informe quantas posições possuem valores iguais.</p>\n<span class=\"badge\" title=\"Compare posição por posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 105 — Soma de Lista (lista)es</strong>\n<p>Leia duas listas com 10 números inteiros cada. Crie um terceira lista contendo a soma dos elementos correspondentes.</p>\n<span class=\"badge\" title=\"A posição da lista resultante depende da mesma posição das duas listas originais.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 106 — Junção de Lista (lista)es</strong>\n<p>Leia duas listas contendo 5 números inteiros cada. Crie um terceira lista contendo todos os elementos das duas listas.</p>\n<span class=\"badge\" title=\"O nova lista terá mais posições do que os listas originais.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 107 — Ranking de Notas</strong>\n<p>Leia as notas de 10 alunos e determine a maior nota, a menor nota e a média da turma.</p>\n<span class=\"badge\" title=\"Você já resolveu problemas parecidos usando repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 108 — Números Acima da Média</strong>\n<p>Leia 15 números reais. Calcule a média e informe quantos valores estão acima dela.</p>\n<span class=\"badge\" title=\"Talvez seja necessário percorrer a lista mais de uma vez.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 109 — Valores em Posições Pares</strong>\n<p>Leia 20 números inteiros e exiba apenas os elementos armazenados em posições pares da lista.</p>\n<span class=\"badge\" title=\"Observe o índice e não o valor armazenado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 110 — Valores em Posições Ímpares</strong>\n<p>Leia 20 números inteiros e exiba apenas os elementos armazenados em posições ímpares.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Listas de listas (listas de listas)</h3><p>Objetivo: usar linhas e colunas para representar tabelas, boletins, vendas e ambientes físicos.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Lista de listas de notas</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja armazenar as notas de 3 alunos em 3 bimestres. Desenvolva um programa que leia essas notas em uma lista de listas 3x3 e depois exiba todos os valores armazenados.</p></div>\n<h4>Programa em Python</h4>\n<pre>notas = []\n\nfor linha in range(3):\n    nova_linha = []\n    for coluna in range(3):\n        nota = float(input(f\"Nota [{linha + 1}][{coluna + 1}]: \"))\n        nova_linha.append(nota)\n    notas.append(nova_linha)\n\nfor linha in notas:\n    for nota in linha:\n        print(nota, end=\" \")\n    print()</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos uma lista de listas 3x3.</li><li>Cada posição é acessada por linha e coluna.</li><li>Usamos dois laços: um para linhas e outro para colunas.</li><li>Depois percorremos novamente a lista de listas para exibir os valores.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 111 — Cadastro em Lista de listas</strong>\n<p>Leia 9 números inteiros e armazene-os em uma lista de listas 3x3. Ao final, exiba todos os valores organizados em formato de tabela.</p>\n<span class=\"badge\" title=\"Você precisará percorrer linhas e colunas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 112 — Soma de Todos os Elementos</strong>\n<p>Leia os valores de uma lista de listas 3x3 e calcule a soma de todos os elementos armazenados.</p>\n<span class=\"badge\" title=\"Some cada elemento à medida que ele for percorrido.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 113 — Média da Lista de listas</strong>\n<p>Leia uma lista de listas 3x3 contendo números reais. Calcule e exiba a média de todos os valores armazenados.</p>\n<span class=\"badge\" title=\"Primeiro obtenha a soma total.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 114 — Maior Elemento</strong>\n<p>Leia uma lista de listas 4x4 e informe qual é o maior valor armazenado.</p>\n<span class=\"badge\" title=\"Compare cada elemento com o maior encontrado até o momento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 115 — Menor Elemento</strong>\n<p>Leia uma lista de listas 4x4 e informe qual é o menor valor armazenado.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 116 — Quantidade de Números Pares</strong>\n<p>Leia uma lista de listas 4x4 e informe quantos elementos possuem valor par.</p>\n<span class=\"badge\" title=\"Verifique cada elemento individualmente.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 117 — Quantidade de Números Ímpares</strong>\n<p>Leia uma lista de listas 4x4 e informe quantos elementos possuem valor ímpar.</p>\n<span class=\"badge\" title=\"Utilize a mesma estratégia do exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 118 — Soma da Linha Informada</strong>\n<p>Leia uma lista de listas 4x4. Em seguida, solicite ao usuário o número de uma linha e calcule a soma dos elementos dessa linha.</p>\n<span class=\"badge\" title=\"Nem todas as linhas precisam ser processadas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 119 — Soma da Coluna Informada</strong>\n<p>Leia uma lista de listas 4x4. Solicite ao usuário o número de uma coluna e calcule a soma dos valores dessa coluna.</p>\n<span class=\"badge\" title=\"Observe qual índice permanece fixo.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 120 — Soma da Diagonal Principal</strong>\n<p>Leia uma lista de listas 4x4 e calcule a soma dos elementos da diagonal principal.</p>\n<span class=\"badge\" title=\"Na diagonal principal, linha e coluna possuem o mesmo índice.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 121 — Soma da Diagonal Secundária</strong>\n<p>Leia uma lista de listas 4x4 e calcule a soma dos elementos da diagonal secundária.</p>\n<span class=\"badge\" title=\"Observe a posição dos elementos que formam a diagonal oposta.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 122 — Boletim Escolar</strong>\n<p>Uma escola deseja armazenar as notas de 5 alunos em 4 bimestres. Use uma lista de listas para armazenar os dados e calcule a média de cada aluno e a média geral da turma.</p>\n<span class=\"badge\" title=\"Cada linha pode representar um aluno.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 123 — Controle de Vendas</strong>\n<p>Uma loja registrou as vendas de 4 vendedores durante 5 dias. Armazene os valores em uma lista de listas e informe o total vendido por vendedor e o total vendido em cada dia.</p>\n<span class=\"badge\" title=\"Linhas e colunas representam informações diferentes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 124 — Ocupação de Estacionamento</strong>\n<p>Um estacionamento possui 5 fileiras com 6 vagas cada. Use uma lista de listas para registrar 0 para vaga livre e 1 para vaga ocupada. Ao final, informe quantas vagas estão ocupadas.</p>\n<span class=\"badge\" title=\"Conte apenas os elementos com valor 1.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 125 — Sala de Aula</strong>\n<p>Uma sala possui 5 fileiras e 5 colunas de carteiras. Use uma lista de listas para representar 0 para carteira vazia e 1 para carteira ocupada. Informe a quantidade de carteiras ocupadas e livres.</p>\n<span class=\"badge\" title=\"Toda lista de listas pode representar um ambiente físico.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 126 — Temperaturas da Semana</strong>\n<p>Uma estação meteorológica registrou temperaturas durante 4 semanas e 7 dias. Armazene os valores em uma lista de listas e informe maior temperatura, menor temperatura e média.</p>\n<span class=\"badge\" title=\"A lista de listas funciona como uma tabela.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 127 — Transposição de lista de listas</strong>\n<p>Leia uma lista de listas 3x3 e exiba sua lista de listas transposta.</p>\n<span class=\"badge\" title=\"Linhas se transformam em colunas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 128 — Soma de listas de listas</strong>\n<p>Leia duas listas de listas 3x3 contendo números inteiros. Crie uma terceira lista de listas contendo a soma dos elementos correspondentes.</p>\n<span class=\"badge\" title=\"Cada posição depende das posições equivalentes das duas listas de listas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 129 — Diferença de listas de listas</strong>\n<p>Leia duas listas de listas 3x3 e gere uma terceira lista de listas contendo a diferença entre os elementos correspondentes.</p>\n<span class=\"badge\" title=\"A lógica é semelhante à soma de listas de listas.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 130 — Pesquisa de Notas</strong>\n<p>Uma escola armazenou as notas de 10 alunos em 4 avaliações. Use uma lista de listas para informar a média de cada aluno, maior nota, menor nota e média geral da turma.</p>\n<span class=\"badge\" title=\"Este exercício reúne praticamente todos os conceitos trabalhados neste nível.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3>Funções</h3><p>Objetivo: dividir programas em partes menores, reutilizar código e organizar soluções.</p>\n<section class=\"exercise-solved\">\n<h3>📘 Exemplo Resolvido — Função</h3>\n<div class=\"example-box\"><strong>Problema:</strong><p>Uma escola deseja exibir uma mensagem de boas-vindas várias vezes durante a execução do programa. Desenvolva um programa utilizando uma função para exibir a mensagem.</p></div>\n<h4>Programa em Python</h4>\n<pre>def enviar_mensagem():\n    print(\"Bem-vindo ao Mundo bit Byte!\")\n\n\nenviar_mensagem()\nenviar_mensagem()\nenviar_mensagem()</pre>\n<h4>Explicação</h4>\n<ol><li>Criamos uma função chamada aviso.</li><li>A função possui uma tarefa específica.</li><li>Sempre que a função é chamada, um aviso é exibido.</li><li>Isso evita repetir o mesmo comando várias vezes no programa principal.</li></ol>\n</section>\n<div class=\"question exercise-item\">\n<strong>Exercício 131 — Função de Saudação</strong>\n<p>Crie uma função que exiba uma mensagem de boas-vindas ao usuário. No programa principal, chame essa função três vezes.</p>\n<span class=\"badge\" title=\"Uma função pode ser executada quantas vezes forem necessárias.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 132 — Função para Linha Decorativa</strong>\n<p>Crie uma função responsável por exibir uma linha contendo 40 caracteres \"-\". Chame a função antes e depois de uma mensagem principal.</p>\n<span class=\"badge\" title=\"A função deve ter apenas uma responsabilidade.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 133 — Função para Tabuada</strong>\n<p>Crie uma função que receba um número inteiro e exiba sua tabuada de 1 até 10.</p>\n<span class=\"badge\" title=\"Funções podem receber informações através de parâmetros.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 134 — Função para Média</strong>\n<p>Crie uma função que receba três notas e exiba a média calculada.</p>\n<span class=\"badge\" title=\"Os valores podem ser enviados à função quando ela for chamada.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 135 — Função para Aprovação</strong>\n<p>Crie uma função que receba uma nota e exiba aprovado ou reprovado conforme o valor recebido.</p>\n<span class=\"badge\" title=\"Você precisará utilizar uma estrutura de decisão dentro da função.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 136 — Função de Soma</strong>\n<p>Crie uma função que receba dois números inteiros e retorne a soma deles. No programa principal, exiba o resultado retornado.</p>\n<span class=\"badge\" title=\"A diferença principal é que a função devolve um valor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 137 — Função para Média</strong>\n<p>Crie uma função que receba três notas e retorne a média aritmética.</p>\n<span class=\"badge\" title=\"O cálculo será feito dentro da função.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 138 — Função Par ou Ímpar</strong>\n<p>Crie uma função que receba um número inteiro e retorne True se o número for par e False se for ímpar.</p>\n<span class=\"badge\" title=\"O operador de resto da divisão será útil.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 139 — Função para Maior Valor</strong>\n<p>Crie uma função que receba dois números e retorne o maior deles.</p>\n<span class=\"badge\" title=\"Use uma estrutura de decisão antes do retorno.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 140 — Função para Menor Valor</strong>\n<p>Crie uma função que receba dois números e retorne o menor deles.</p>\n<span class=\"badge\" title=\"A lógica é semelhante ao exercício anterior.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 141 — Função de Potência</strong>\n<p>Crie uma função que receba uma base e um expoente inteiro positivo e retorne o resultado da potência.</p>\n<span class=\"badge\" title=\"Você pode utilizar repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 142 — Função de IMC</strong>\n<p>Crie uma função que receba peso e altura e retorne o valor do IMC calculado.</p>\n<span class=\"badge\" title=\"A função deve apenas calcular e retornar o resultado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 143 — Função de Fatorial</strong>\n<p>Crie uma função que receba um número inteiro positivo e retorne seu fatorial.</p>\n<span class=\"badge\" title=\"Utilize um acumulador para realizar as multiplicações.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 144 — Função para Número Primo</strong>\n<p>Crie uma função que receba um número inteiro positivo e informe se ele é primo.</p>\n<span class=\"badge\" title=\"A função deve analisar os divisores do número.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 145 — Função para Cadastro de Aluno</strong>\n<p>Crie uma função que receba nome, nota 1 e nota 2. A função deverá calcular a média e exibir um relatório simples do aluno.</p>\n<span class=\"badge\" title=\"Agrupe tarefas relacionadas em uma única função.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 146 — Função para Desconto</strong>\n<p>Crie uma função que receba o valor de um produto e um percentual de desconto e retorne o valor final.</p>\n<span class=\"badge\" title=\"A função deve devolver apenas o valor calculado.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 147 — Função para Conversão de Temperatura</strong>\n<p>Crie uma função que receba uma temperatura em Celsius e retorne o valor correspondente em Fahrenheit.</p>\n<span class=\"badge\" title=\"A fórmula deve ficar dentro da função.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 148 — Função para Relatório de Vendas</strong>\n<p>Crie uma função que receba nome do vendedor, quantidade vendida e valor total vendido. A função deverá exibir um relatório organizado na tela.</p>\n<span class=\"badge\" title=\"A função será responsável apenas pela apresentação dos dados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 149 — Função para Verificar Aprovação</strong>\n<p>Crie uma função que receba a média de um aluno e retorne True para aprovado e False para reprovado. Considere média mínima igual a 6.</p>\n<span class=\"badge\" title=\"O retorno da função pode ser lógico.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 150 — Sistema Modularizado</strong>\n<p>Desenvolva um programa que utilize pelo menos quatro funções, separando cálculos e apresentação. O programa deve ler dados de um aluno, calcular sua média e exibir um relatório final.</p>\n<span class=\"badge\" title=\"Divida o problema em partes menores e reutilizáveis.\">💡 Dica</span>\n</div></section><section class=\"exercise-level\"><h3> Desafios</h3><p>Objetivo: integrar variáveis, decisões, repetições, listas, listas de listas, funções que realizam ações e funções que devolvem valores em problemas maiores.</p>\n<div class=\"question exercise-item\">\n<strong>Exercício 151 — Boletim Escolar Completo</strong>\n<p>Desenvolva um programa para registrar as notas de uma turma. O programa deve ler o nome de 10 alunos e suas quatro notas bimestrais. Ao final, exiba a média de cada aluno e informe se ele foi aprovado ou reprovado.</p>\n<span class=\"badge\" title=\"Use listas para nomes e médias. A aprovação depende de uma decisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 152 — Controle de Estoque</strong>\n<p>Uma loja deseja controlar 10 produtos. Para cada produto, leia o nome, a quantidade em estoque e o preço unitário. Ao final, informe o valor total armazenado em estoque e qual produto possui maior quantidade.</p>\n<span class=\"badge\" title=\"Cada produto possui mais de uma informação.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 153 — Sistema de Biblioteca</strong>\n<p>Crie um programa para registrar 10 livros de uma biblioteca. Para cada livro, leia título, autor e quantidade disponível. Ao final, permita pesquisar um título e informe se ele está cadastrado.</p>\n<span class=\"badge\" title=\"Será necessário percorrer os registros armazenados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 154 — Controle de Vendas</strong>\n<p>Uma loja registrou as vendas de 5 vendedores durante 4 semanas. Armazene os valores em uma lista de listas e informe o total vendido por cada vendedor e o total geral da loja.</p>\n<span class=\"badge\" title=\"Cada linha pode representar um vendedor.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 155 — Caixa Eletrônico Simples</strong>\n<p>Desenvolva um programa que leia um valor inteiro para saque e informe quantas notas de 100, 50, 20, 10 e 5 serão necessárias.</p>\n<span class=\"badge\" title=\"Use divisão inteira e resto da divisão.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 156 — Pesquisa de Satisfação</strong>\n<p>Uma empresa entrevistou 30 clientes. Cada cliente informou uma nota de 1 a 5. Ao final, exiba a média das avaliações e a quantidade de votos em cada nota.</p>\n<span class=\"badge\" title=\"Crie contadores separados para cada nota.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 157 — Campeonato Escolar</strong>\n<p>Leia o nome de 6 equipes e a pontuação de cada uma. Ao final, informe a equipe campeã, a menor pontuação e a média de pontos do campeonato.</p>\n<span class=\"badge\" title=\"Compare os pontos enquanto percorre os dados.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 158 — Agenda de Contatos</strong>\n<p>Crie um programa para cadastrar 10 contatos, contendo nome e telefone. Depois, permita pesquisar um nome e exibir o telefone correspondente.</p>\n<span class=\"badge\" title=\"Use duas listas relacionadas pela mesma posição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 159 — Jogo de Adivinhação</strong>\n<p>Defina um número secreto dentro do programa. O usuário deve tentar adivinhar o número. A cada tentativa, informe se o valor digitado é maior ou menor que o número secreto. O jogo termina quando acertar.</p>\n<span class=\"badge\" title=\"Use repetição com condição de parada.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 160 — Sistema de Notas com Funções</strong>\n<p>Crie um programa modularizado para calcular a média de um aluno. Use uma função para calcular a média e uma função para exibir o relatório final.</p>\n<span class=\"badge\" title=\"Separe cálculo e exibição em partes diferentes.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 161 — Controle de Despesas</strong>\n<p>Leia os gastos de uma pessoa durante 12 meses. Ao final, exiba o total gasto no ano, a média mensal e o mês com maior despesa.</p>\n<span class=\"badge\" title=\"Uma lista pode representar os meses do ano.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 162 — Temperaturas do Mês</strong>\n<p>Leia as temperaturas registradas em 30 dias. Exiba a maior temperatura, a menor temperatura, a média e quantos dias ficaram acima da média.</p>\n<span class=\"badge\" title=\"Talvez seja necessário percorrer os dados mais de uma vez.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 163 — Urna Eletrônica Simples</strong>\n<p>Crie um programa que simule uma votação com três candidatos. Leia os votos de 20 eleitores e informe o total de votos de cada candidato e o vencedor.</p>\n<span class=\"badge\" title=\"Cada candidato precisa de um contador.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 164 — Ranking de Alunos</strong>\n<p>Leia o nome e a média de 10 alunos. Exiba o aluno com maior média, o aluno com menor média e a média geral da turma.</p>\n<span class=\"badge\" title=\"Guarde nome e nota na mesma posição lógica.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 165 — Estacionamento</strong>\n<p>Um estacionamento possui 5 fileiras com 6 vagas. Leia a ocupação das vagas usando 0 para livre e 1 para ocupada. Ao final, informe o total de vagas livres e ocupadas.</p>\n<span class=\"badge\" title=\"A lista de listas representa o espaço físico do estacionamento.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 166 — Controle de Produtos Vencidos</strong>\n<p>Cadastre 10 produtos com nome, quantidade e dias restantes para vencimento. Ao final, informe quais produtos vencem em até 7 dias.</p>\n<span class=\"badge\" title=\"Use uma decisão durante a exibição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 167 — Simulador de Atendimento</strong>\n<p>Um sistema deve registrar 15 atendimentos. Para cada atendimento, leia o tempo gasto em minutos. Ao final, informe o tempo médio, o maior tempo e o menor tempo.</p>\n<span class=\"badge\" title=\"É um exercício de estatística com repetição.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 168 — Pedido de Lanchonete</strong>\n<p>Crie um programa com um menu de produtos. O usuário deve escolher itens e quantidades. O pedido termina quando escolher a opção sair. Ao final, exiba o total da compra.</p>\n<span class=\"badge\" title=\"Use repetição enquanto o usuário não escolher sair.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 169 — Análise de Números</strong>\n<p>Leia 20 números inteiros e informe quantos são positivos, negativos, pares, ímpares e múltiplos de 5.</p>\n<span class=\"badge\" title=\"Um mesmo número pode entrar em mais de uma classificação.\">💡 Dica</span>\n</div>\n<div class=\"question exercise-item\">\n<strong>Exercício 170 — Projeto Livre</strong>\n<p>Crie um programa próprio usando pelo menos três conteúdos estudados no módulo, como decisão, repetição, lista, lista de listas ou função. O programa deve ter entrada de dados, processamento e saída organizada.</p>\n<span class=\"badge\" title=\"Pense primeiro no problema, depois nos dados necessários e só então nos comandos.\">💡 Dica</span>\n</div></section>\n</div>\n"
  };
})();
